export function StarRow({ rating = 5, size = "text-sm" }: { rating?: number; size?: string }) {
  const filled = Math.max(0, Math.min(5, rating));
  return (
    <span className={`tracking-[0.12em] ${size}`} aria-label={`${filled} out of 5 stars`}>
      <span className="text-amber-300">{"★".repeat(filled)}</span>
      <span className="text-white/15">{"★".repeat(5 - filled)}</span>
    </span>
  );
}

