/** Icon keys used by the AI-hosting preview data, resolved to shared icons. */
export type IconKey = "spark" | "check" | "import" | "server" | "bolt" | "code" | "globe" | "shield";

const MAP: Record<IconKey, (p: { size?: number; className?: string }) => React.ReactElement> = {
  spark: IconSpark,
  check: IconCheck,
  import: IconArrow,
  server: IconServer,
  bolt: IconBolt,
  code: IconCode,
  globe: IconGlobe,
  shield: IconShield,
};

export function ReasonIcon({ icon, size = 20, className }: { icon: IconKey; size?: number; className?: string }) {
  const C = MAP[icon];
  return <C size={size} className={className} />;
}

/* Co-located CSS Module for the AI-hosting preview template. Scoped keyframes
   that the shipped design system doesn't already provide. Every animation is
   disabled under prefers-reduced-motion. Preview-only; never imported by a live
   page. */

/* Continuous horizontal marquee (import-source / stack ribbon). The track is
   rendered twice back-to-back so a -50% translate loops seamlessly. */
.marqueeTrack {
  display: flex;
  width: max-content;
  animation: ai-marquee 26s linear infinite;
}
.marquee:hover .marqueeTrack {
  animation-play-state: paused;
}
@keyframes ai-marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* Slow aurora drift for the hero backdrop — cheap opacity/transform only. */
.aurora {
  animation: ai-aurora 14s ease-in-out infinite alternate;
}
@keyframes ai-aurora {
  from {
    transform: translate3d(-2%, 0, 0) scale(1);
    opacity: 0.7;
  }
  to {
    transform: translate3d(3%, -2%, 0) scale(1.08);
    opacity: 1;
  }
}

/* A soft rise-in used for the assembling browser preview blocks. */
.rise {
  opacity: 0;
  transform: translateY(10px);
  animation: ai-rise 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes ai-rise {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .marqueeTrack,
  .aurora,
  .rise {
    animation: none;
  }
  .rise {
    opacity: 1;
    transform: none;
  }
}

