/* ── Hero centerpiece: describe → build → deploy → live ──────────────────── */
function BuildConsole() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const [typed, setTyped] = useState("");
  const [phase, setPhase] = useState<"idle" | "typing" | "building" | "deploying" | "live">("idle");
  const [built, setBuilt] = useState(0);
  const [deployed, setDeployed] = useState(0);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    if (!seen) return;
    if (reduced) {
      setTyped(BUILD_PROMPT);
      setBuilt(BUILD_STEPS.length);
      setDeployed(DEPLOY_STEPS.length);
      setPhase("live");
      return;
    }
    let dead = false;
    const push = (fn: () => void, ms: number) => {
      if (!dead) timers.current.push(setTimeout(fn, ms));
    };
    const run = () => {
      setTyped("");
      setBuilt(0);
      setDeployed(0);
      setPhase("typing");
      const charMs = 34;
      BUILD_PROMPT.split("").forEach((_, i) => push(() => setTyped(BUILD_PROMPT.slice(0, i + 1)), 300 + charMs * i));
      const afterType = 300 + charMs * BUILD_PROMPT.length + 500;
      push(() => setPhase("building"), afterType);
      BUILD_STEPS.forEach((_, i) => push(() => setBuilt(i + 1), afterType + 720 * (i + 1)));
      const afterBuild = afterType + 720 * (BUILD_STEPS.length + 1);
      push(() => setPhase("deploying"), afterBuild);
      DEPLOY_STEPS.forEach((_, i) => push(() => setDeployed(i + 1), afterBuild + 640 * (i + 1)));
      const afterDeploy = afterBuild + 640 * (DEPLOY_STEPS.length + 1);
      push(() => setPhase("live"), afterDeploy);
      push(run, afterDeploy + 5200); // loop
    };
    run();
    return () => {
      dead = true;
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
  }, [seen, reduced]);

  const showSite = phase === "live";

  return (
    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
      <div className="relative grid gap-4 sm:grid-cols-[1.05fr_0.95fr] sm:items-start">
        {/* ambient glow behind the console */}
        <div
          className="pointer-events-none absolute -inset-10 -z-10 opacity-70"
          style={{
            background:
              "radial-gradient(45% 45% at 15% 0%, rgba(59,130,246,0.22), transparent 70%), radial-gradient(45% 50% at 95% 100%, rgba(138,112,251,0.24), transparent 70%)",
          }}
          aria-hidden
        />

        {/* Claude chat / build panel */}
        <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
          <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
            <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-accent-blue to-brand-500 text-white">
              <ClaudeMark size={13} />
            </span>
            <span className="text-[12px] font-medium text-slate-300">Claude · connected to your server</span>
            <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
              live
            </span>
          </div>

          <div className="space-y-3 px-4 py-4 text-[13px] leading-relaxed">
            {/* user prompt (typing) */}
            <div className="ml-auto max-w-[88%] rounded-2xl rounded-br-sm border border-brand-500/25 bg-brand-500/10 px-3.5 py-2.5 text-slate-100">
              {typed || <span className="text-slate-500">Describe what you want to build…</span>}
              {phase === "typing" && (
                <span className="ml-0.5 inline-block h-3.5 w-1.5 translate-y-[2px] bg-brand-300 motion-safe:animate-blink" />
              )}
            </div>

            {/* claude building */}
            {(phase === "building" || phase === "deploying" || phase === "live") && (
              <div className="max-w-[94%] rounded-2xl rounded-bl-sm border border-white/[0.07] bg-white/[0.03] px-3.5 py-3">
                <p className="text-slate-300">On it — here&apos;s the plan:</p>
                <ul className="mt-2.5 space-y-1.5 font-mono text-[12px]">
                  {BUILD_STEPS.map((s, i) => {
                    const done = built > i;
                    return (
                      <li key={s.label} className={`flex items-center gap-2 ${done ? "text-slate-300" : "text-slate-600"}`}>
                        <span
                          className={`flex h-3.5 w-3.5 shrink-0 items-center justify-center rounded-full ${
                            done ? "bg-emerald-500/15 text-emerald-400" : "border border-white/10 text-transparent"
                          }`}
                        >
                          <IconCheck size={10} />
                        </span>
                        <span className="flex-1">{s.label}</span>
                        <span className="text-slate-600">{s.detail}</span>
                      </li>
                    );
                  })}
                </ul>

                {/* review-before-ship gate (honesty) */}
                {(phase === "deploying" || phase === "live") && (
                  <div className="mt-3 flex items-center gap-2 rounded-lg border border-brand-500/25 bg-brand-500/[0.08] px-2.5 py-1.5 text-[11px] text-brand-200">
