                {/* deploy stream */}
                {(phase === "deploying" || phase === "live") && (
                  <div className="mt-2.5 space-y-0.5 font-mono text-[11.5px]">
                    {DEPLOY_STEPS.slice(0, deployed).map((l, i) => {
