                    <span className="mt-2 inline-block rounded-full bg-emerald-700 px-3 py-1 text-[10px] font-semibold text-white">
                      Book an appointment
                    </span>
                  </div>
                  <div className="mt-3 grid grid-cols-3 gap-2">
                    {["Massage", "Facials", "Sauna"].map((s, i) => (
                      <div
                        key={s}
                        className={`rounded-lg bg-white p-2 text-left shadow-sm ring-1 ring-black/5 ${reduced ? "" : styles.rise}`}
                        style={{ animationDelay: `${180 + i * 90}ms` }}
                      >
                        <div className="mb-1.5 h-6 rounded bg-emerald-100" />
                        <p className="text-[9px] font-semibold text-slate-700">{s}</p>
                        <p className="text-[8px] text-slate-400">from $60</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
          {/* live tag under the browser */}
          <div className="mt-3 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-3 py-1.5 text-[12px] text-slate-300 backdrop-blur-md">
            <LiveDot />
            {showSite ? (
              <>
                <span className="font-semibold text-accent-cyan">Live</span> · HTTPS issued · 47s from prompt
              </>
            ) : (
              <>Deploying to your server…</>
            )}
          </div>
        </div>
      </div>
    </div>
  );
