/**
 * Co-located client kit for the shared web-hosting PREVIEW template
 * (components/marketing/webhostingtemplate/*). Self-contained hooks + atoms so
 * the template is isolated and independently shippable. Everything respects
 * prefers-reduced-motion: motion hooks resolve to their final resting value.
 *
 * Net-new, preview-only. Touches no live page or shared component.
 */

import { useEffect, useRef, useState } from "react";

export function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    if (!mq) return;
    setReduced(mq.matches);
    const on = () => setReduced(mq.matches);
    mq.addEventListener?.("change", on);
    return () => mq.removeEventListener?.("change", on);
  }, []);
  return reduced;
}

/** Fires once when the element first scrolls into view. */
export function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
  const ref = useRef<T | null>(null);
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setSeen(true);
      return;
    }
    const io = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          setSeen(true);
          io.disconnect();
        }
      },
      { threshold: 0.2, rootMargin: margin },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [margin]);
  return { ref, seen };
}

/** Smoothly counts up to `target` once `active`. Immediate under reduced motion. */
export function useCountUp(target: number, active: boolean, duration = 1100, reduced = false) {
  const [val, setVal] = useState(reduced ? target : 0);
  useEffect(() => {
    if (!active) return;
    if (reduced) {
      setVal(target);
      return;
    }
    let raf = 0;
    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - t, 3);
      setVal(Math.round(target * eased));
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [target, active, duration, reduced]);
  return val;
}

/** Compact amber 5-star row (matches the shipped ReviewCarousel/StarRow treatment). */
export function StarRow({ rating = 5, size = "text-sm" }: { rating?: number; size?: string }) {
  const filled = Math.max(0, Math.min(5, rating));
  return (
    <span className={`tracking-[0.12em] ${size}`} aria-label={`${filled} out of 5 stars`}>
      <span className="text-amber-300">{"★".repeat(filled)}</span>
      <span className="text-white/15">{"★".repeat(5 - filled)}</span>
    </span>
  );
}

