/* Co-located CSS Module for the web-hosting preview template. Scoped keyframes
   the shipped design system doesn't already provide. Every animation is disabled
   under prefers-reduced-motion. Preview-only; never imported by a live page. */

/* Continuous horizontal marquee (one-click apps ribbon). Track rendered twice
   so a -50% translate loops seamlessly. */
.marqueeTrack {
  display: flex;
  width: max-content;
  animation: wh-marquee 30s linear infinite;
}
.marquee:hover .marqueeTrack {
  animation-play-state: paused;
}
@keyframes wh-marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* Soft rise-in for the assembling WordPress site preview blocks. */
.rise {
  opacity: 0;
  transform: translateY(10px);
  animation: wh-rise 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes wh-rise {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Grow-from-bottom for the flat-vs-hike price bars. `--wh-h` is the target
   height; the bar animates up to it. */
.bar {
  height: 0;
  animation: wh-bar 0.9s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes wh-bar {
  to {
    height: var(--wh-h, 40%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .marqueeTrack,
  .rise,
  .bar {
    animation: none;
  }
  .rise {
    opacity: 1;
    transform: none;
  }
  .bar {
    height: var(--wh-h, 40%);
  }
}

