/* ── Hero centerpiece: one-click install → live site ─────────────────────── */
function InstallToLive() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const [installed, setInstalled] = useState(0);
  const [phase, setPhase] = useState<"idle" | "installing" | "live">("idle");
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    if (!seen) return;
    if (reduced) {
      setInstalled(INSTALL_STEPS.length);
      setPhase("live");
      return;
    }
    let dead = false;
    const push = (fn: () => void, ms: number) => {
      if (!dead) timers.current.push(setTimeout(fn, ms));
    };
    const run = () => {
      setInstalled(0);
      setPhase("installing");
      INSTALL_STEPS.forEach((_, i) => push(() => setInstalled(i + 1), 600 + 720 * (i + 1)));
      const done = 600 + 720 * (INSTALL_STEPS.length + 1);
      push(() => setPhase("live"), done);
      push(run, done + 5200); // loop
    };
    run();
    return () => {
      dead = true;
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
  }, [seen, reduced]);

  const live = phase === "live";

  return (
    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
      <div className="relative grid gap-4 sm:grid-cols-[0.92fr_1.08fr] sm:items-start">
        <div
          className="pointer-events-none absolute -inset-10 -z-10 opacity-70"
          style={{
            background:
              "radial-gradient(45% 45% at 10% 0%, rgba(59,130,246,0.20), transparent 70%), radial-gradient(45% 50% at 95% 100%, rgba(111,71,245,0.22), transparent 70%)",
          }}
          aria-hidden
        />

        {/* install panel */}
        <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
          <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
            <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-accent-blue to-brand-500 text-white">
              <IconApps size={13} />
            </span>
            <span className="text-[12px] font-medium text-slate-300">One-click installer</span>
            <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
              {live ? "installed" : "installing"}
            </span>
