/* ── Migration flow (handled vs flagged, honest) ─────────────────────────── */
function MigrationFlow() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const [shown, setShown] = useState(reduced ? MIGRATION_STEPS.length : 0);

  useEffect(() => {
    if (!seen) return;
    if (reduced) {
      setShown(MIGRATION_STEPS.length);
      return;
    }
    let i = 0;
    let t: ReturnType<typeof setTimeout>;
    const tick = () => {
      i += 1;
      setShown(i);
      if (i < MIGRATION_STEPS.length) t = setTimeout(tick, 620);
    };
    t = setTimeout(tick, 500);
    return () => clearTimeout(t);
  }, [seen, reduced]);

  return (
    <div ref={ref} className="rounded-2xl border border-white/10 bg-black/40 p-5 font-mono text-[12.5px] leading-relaxed shadow-2xl">
      <div className="mb-3 flex items-center gap-1.5">
        <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
        <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
        <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
        <span className="ml-2 text-[11px] uppercase tracking-widest text-slate-500">nxeon · migrate</span>
      </div>
      <div className="min-h-[152px] space-y-1.5">
        {MIGRATION_STEPS.slice(0, shown).map((s, i) => (
          <div key={i} className="flex items-center gap-2">
            {s.status === "done" ? (
              <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                <IconCheck size={11} />
              </span>
            ) : (
              <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-amber-400/15 text-amber-300">!</span>
            )}
            <span className={s.status === "flagged" ? "text-amber-200" : "text-slate-300"}>{s.label}</span>
          </div>
        ))}
        {shown >= MIGRATION_STEPS.length && (
          <div className="mt-2 flex items-center gap-2 rounded-lg border border-emerald-400/20 bg-emerald-400/[0.06] px-3 py-2 text-[11.5px] text-emerald-300">
            <LiveDot />
            Migration complete · 1 item flagged for your review · no downtime
          </div>
        )}
      </div>
    </div>
  );
}

