                  <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full border border-brand-500/30 bg-brand-500/15 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.12em] text-brand-200">
                    Most popular
                  </span>
                )}
                <h3 className="text-lg font-semibold text-white">{p.name}</h3>
                <p className="mt-2">
                  <span className="text-4xl font-bold text-white">{p.price}</span>
                  <span className="text-sm text-slate-500">/mo</span>
                </p>
                <p className="mt-1 text-[11px] font-medium text-accent-cyan">Same price at renewal</p>
                <p className="mt-2 text-sm leading-relaxed text-slate-400">{p.blurb}</p>
                <ul className="mt-5 flex-1 space-y-2.5 border-t border-white/[0.06] pt-5">
                  {p.specs.map((f) => (
                    <li key={f} className="flex items-start gap-2.5 text-sm text-slate-300">
                      <span className="mt-0.5 flex h-[18px] w-[18px] shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                        <IconCheck size={12} />
                      </span>
                      {f}
                    </li>
                  ))}
                </ul>
                <Link
                  href="/dashboard/hosting"
                  className={`mt-6 block rounded-xl px-4 py-2.5 text-center text-sm font-semibold ${p.popular ? "btn-deploy" : "btn-secondary"}`}
                >
                  Get started
                </Link>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ── FREE MIGRATION ────────────────────────────────────────────────── */}
      <section id="migrate" className="rail scroll-mt-24 py-24">
        <div className="grid items-center gap-12 lg:grid-cols-2 lg:gap-14">
          <div>
            <span className="eyebrow">Free migration</span>
            <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
              Already have a site? We move it <span className="grad-text">free</span>
            </h2>
            <p className="mt-4 max-w-md text-lg leading-relaxed text-slate-400">
              We bring your files, databases, email and configuration across, then help you cut the domain over with no
              downtime. Anything that needs a human eye gets flagged for your review — nothing is silently changed.
            </p>
            <Link href="/migrate" className="btn-primary mt-7 inline-flex px-6 py-3 text-base">
              Start my free migration
              <IconArrow size={16} />
            </Link>
          </div>
          <MigrationFlow />
        </div>
      </section>

      {/* ── REVIEWS ───────────────────────────────────────────────────────── */}
      <section className="tone-panel py-24">
        <div className="rail">
          <div className="mx-auto max-w-2xl text-center">
            <div className="flex items-center justify-center gap-3">
              <StarRow rating={5} size="text-base" />
              <span className="text-sm text-slate-400">
                <span className="font-semibold text-white">{RATING_AVG} / 5</span> average
              </span>
            </div>
            <h2 className="mt-4 text-3xl font-bold tracking-tight text-white sm:text-4xl">{RATING_LABEL}</h2>
          </div>
          <div className="mt-12 grid gap-4 md:grid-cols-3">
            {REVIEWS.map((rv) => (
              <figure key={rv.id} className="card flex flex-col">
                <StarRow rating={rv.rating} />
                <blockquote className="mt-4 flex-1 text-sm leading-relaxed text-slate-300">&ldquo;{rv.quote}&rdquo;</blockquote>
                <figcaption className="mt-5 flex items-center gap-3 border-t border-white/[0.06] pt-4">
                  <span className="flex h-9 w-9 items-center justify-center rounded-full bg-gradient-to-br from-brand-500 to-accent-blue text-sm font-semibold text-white">
                    {rv.name.charAt(0)}
                  </span>
                  <span>
                    <span className="block text-sm font-semibold text-white">{rv.name}</span>
                    <span className="block text-xs text-slate-500">{rv.meta}</span>
                  </span>
                </figcaption>
              </figure>
            ))}
          </div>
        </div>
      </section>

      {/* ── CLOSING CTA ───────────────────────────────────────────────────── */}
      <section className="relative isolate overflow-hidden py-28">
        <div
          className="pointer-events-none absolute inset-0 -z-10"
          style={{
            background:
              "radial-gradient(50% 60% at 20% 100%, rgba(59,130,246,0.16), transparent 70%), radial-gradient(45% 55% at 85% 0%, rgba(111,71,245,0.14), transparent 70%)",
          }}
          aria-hidden
        />
        <div className="rail text-center">
          <h2 className="mx-auto max-w-2xl text-3xl font-bold tracking-tight text-white sm:text-5xl">
            Your site is <span className="grad-text">47 seconds</span> from live.
          </h2>
          <p className="mx-auto mt-5 max-w-xl text-lg text-slate-300">
            One-click install, free SSL, free migration — and a price that never jumps at renewal.
          </p>
          <div className="mt-9 flex flex-wrap justify-center gap-3">
            <Link href="/dashboard/hosting" className="btn-deploy px-7 py-3.5 text-base">
              Get started
              <span className="dep-arrow" aria-hidden>
                →
              </span>
            </Link>
            <Link href="/migrate" className="btn-secondary px-6 py-3.5 text-base">
              Migrate my site free
            </Link>
          </div>
          <p className="mt-4 flex items-center justify-center gap-1.5 text-xs text-slate-500">
            <IconBolt size={13} /> No setup fees · no renewal price hikes · cancel anytime
          </p>
        </div>
      </section>
    </div>
  );
}

function FeatureCard({ f, delay }: { f: (typeof FEATURES)[number]; delay: number }) {
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  return (
    <div
      ref={ref}
      className={`group relative overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/50 p-6 transition-all duration-700 ease-out hover:border-white/15 ${
        seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"
      }`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      <span className="flex h-11 w-11 items-center justify-center rounded-xl border border-white/10 bg-gradient-to-br from-brand-500/25 to-transparent text-brand-300">
        <FeatureIcon icon={f.icon} size={20} />
      </span>
      <h3 className="mt-5 text-base font-semibold text-white">{f.title}</h3>
      <p className="mt-2 text-sm leading-relaxed text-slate-400">{f.body}</p>
    </div>
  );
}

